// End-to-end checks against the real Electron app, driven over Chrome DevTools.
// Each scenario launches the app on a given user-data directory, runs its steps in the
// page, and closes the app. Reusing one directory across two launches tests persistence.
//
// Usage:
//   node --experimental-websocket scripts/e2e-app.mjs <scenario> <userDataDir> [port]
// Scenarios: feedback-ask, feedback-check, reset-populate, reset-verify,
//            conversation-ask (asks two questions, then reloads), conversation-check (after restart)
import { spawn } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';
import { fileURLToPath } from 'url';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const [scenario, userData, portArg] = process.argv.slice(2);
const port = portArg || '9361';
if (!scenario || !userData) {
  console.error('usage: e2e-app.mjs <scenario> <userDataDir> [port]');
  process.exit(2);
}

const env = { ...process.env };
delete env.NODE_OPTIONS;
const electron = spawn('npx', ['electron', '.', `--remote-debugging-port=${port}`, `--user-data-dir=${userData}`], {
  cwd: root,
  env,
  stdio: 'ignore',
});

async function connect() {
  for (let i = 0; i < 60; i++) {
    try {
      const targets = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
      const page = targets.find(t => t.type === 'page');
      if (page) {
        const ws = new WebSocket(page.webSocketDebuggerUrl);
        await new Promise((resolve, reject) => {
          ws.addEventListener('open', resolve);
          ws.addEventListener('error', reject);
        });
        return ws;
      }
    } catch {
      // not up yet
    }
    await new Promise(r => setTimeout(r, 500));
  }
  throw new Error('Electron did not expose a page on the DevTools port');
}

const ws = await connect();
let nextId = 1;
const pending = new Map();
ws.addEventListener('message', ev => {
  const msg = JSON.parse(ev.data);
  const resolve = pending.get(msg.id);
  if (!resolve) return;
  pending.delete(msg.id);
  resolve(msg);

